SELECT * FROM (SELECT method, status, amount FROM payments)
PIVOT (MAX(amount) FOR status IN ('FAILED', 'SUCCESS', 'REFUNDED'))
ORDER BY method;

SELECT * FROM (SELECT status, carrier, cost FROM shipments)
PIVOT (COUNT(cost) FOR carrier IN ('DHL', 'FedEx'))
ORDER BY status;

SELECT * FROM (SELECT city, country, rating FROM suppliers)
PIVOT (SUM(rating) FOR country IN ('SG', 'DE', 'TH', 'UK'))
ORDER BY city;

select * from (select txn_type, merchant, amount from transactions)
pivot (avg(amount) for merchant in ('7-Eleven', 'Amazon', 'Starbucks', 'Grab'))
order by txn_type;

SELECT * FROM (SELECT segment, city, credit_limit FROM customers)
PIVOT (MAX(credit_limit) FOR city IN ('Tokyo', 'Berlin', 'Chiang Mai', 'London'))
ORDER BY segment;

SELECT * FROM (SELECT event_type, page, duration_sec FROM web_events)
PIVOT (AVG(duration_sec) FOR page IN ('/cart', '/checkout', '/home'))
ORDER BY event_type;

SELECT * FROM (SELECT status, plan, monthly_fee FROM subscriptions)
PIVOT (COUNT(monthly_fee) FOR plan IN ('enterprise', 'basic', 'premium'))
ORDER BY status;

select * from (select city, region, sqft from stores)
pivot (count(sqft) for region in ('North', 'East', 'Central', 'West'))
order by city;

SELECT * FROM (SELECT country, segment, credit_limit FROM customers)
PIVOT (MAX(credit_limit) FOR segment IN ('SMB', 'Corporate'))
ORDER BY country;

select * from (select level, job_title, salary from employees)
pivot (sum(salary) for job_title in ('Intern', 'Manager', 'Analyst', 'Designer'))
order by level;

select * from (select plan, status, monthly_fee from subscriptions)
pivot (count(monthly_fee) for status in ('PAUSED', 'CANCELLED', 'ACTIVE', 'EXPIRED'))
order by plan;

SELECT * FROM (SELECT carrier, status, cost FROM shipments)
PIVOT (AVG(cost) FOR status IN ('RETURNED', 'DELIVERED'))
ORDER BY carrier;

SELECT * FROM (SELECT is_active, city, credit_limit FROM customers)
PIVOT (AVG(credit_limit) FOR city IN ('New York', 'Bangkok', 'London'))
ORDER BY is_active;

select * from (select city, country, age from customers)
pivot (avg(age) for country in ('US', 'JP', 'UK'))
order by city;

SELECT * FROM (SELECT account_type, status, balance FROM accounts)
PIVOT (COUNT(balance) FOR status IN ('FROZEN', 'OPEN', 'CLOSED'))
ORDER BY account_type;

SELECT * FROM (SELECT city, region, sqft FROM stores)
PIVOT (SUM(sqft) FOR region IN ('Central', 'East', 'South'))
ORDER BY city;

SELECT * FROM (SELECT category, brand, price FROM products)
PIVOT (MAX(price) FOR brand IN ('Umbrella', 'Stark', 'Acme', 'Initech'))
ORDER BY category;

select *
from (
    select
        firmware,
        device_code,
        temp_c
    from device_readings
) src
pivot (
    max(temp_c) as value_sum
    for device_code in ('DV-02' as dv_02, 'DV-04' as dv_04, 'DV-01' as dv_01)
);

select *
from (
    select
        order_id,
        status,
        amount
    from payments
) src
pivot (
    max(amount)
    for status in ('SUCCESS' as success, 'FAILED' as failed)
)

select *
from promotions
qualify row_number() over (partition by channel order by discount_pct desc, id) = 1;

select *
from (
    select date_format(signup_date, 'yyyy-MM') as signup_month, round(avg(credit_limit), 2) as avg_credit_limit
    from customers
    where country in ('JP', 'UK')
    group by date_format(signup_date, 'yyyy-MM')
) as x
where avg_credit_limit > 71
order by signup_month desc
limit 50;

select e.email as employee_email, e.job_title as employee_job_title, m.job_title as manager_job_title
from employees e
left join employees m on e.manager_id = m.id;

select *
from (
    select product_id, sum(quantity) as total_quantity, count(quantity) as quantity_count
    from inventory
    where store_id in (2, 3, 4, 6)
    group by product_id
) as x
where quantity_count < 9
order by total_quantity;

SELECT id, txn_time, TO_DATE(txn_time) AS txn_time_date
FROM transactions
WHERE is_flagged = TRUE OR txn_type = 'CREDIT';

SELECT id, budget, ROW_NUMBER() OVER (ORDER BY budget, id) AS rn
FROM departments
WHERE location IS NOT NULL;

select product_id, unit_price, coalesce(quantity, 0) as quantity_filled
from order_items
where product_id in (18, 30, 32);

SELECT p.id, p.method, p.status
FROM payments p
WHERE p.order_id IN (12, 31) AND p.order_id NOT IN (SELECT id FROM orders WHERE order_date < '2025-03-01');

SELECT DISTINCT category
FROM products
WHERE LENGTH(product_name) > 5;

SELECT *, SUBSTRING(store_name, 1, 2) AS store_name_prefix, SUBSTRING(store_name, 1, 4) AS store_name_prefix_2
FROM stores
WHERE opened_date BETWEEN '2023-10-01' AND '2024-10-01' AND MONTH(opened_date) IN (1, 6, 10);

SELECT o.id, o.amount, o.channel
FROM orders o
WHERE o.customer_id NOT IN (SELECT id FROM customers WHERE UPPER(email) LIKE '%ENR%');

SELECT s.id, s.monthly_fee, s.plan
FROM subscriptions s
WHERE s.customer_id NOT IN (SELECT id FROM customers WHERE LOWER(TRIM(email)) = 'henry@startup.io');

SELECT s.id, s.shipped_date
FROM shipments s
WHERE s.order_id NOT IN (SELECT id FROM orders WHERE discount <= 0.2);

SELECT we.id, we.duration_sec
FROM web_events we
WHERE we.session_id NOT IN (SELECT id FROM sessions WHERE HOUR(started_at) BETWEEN 10 AND 13);

SELECT p.id, p.status
FROM payments p
WHERE p.order_id NOT IN (SELECT id FROM orders WHERE shipping_fee < 24);

select oi.id, oi.product_id
from order_items oi
where oi.product_id not in (select id from products where array_contains(tags, 'bestseller'));

SELECT p.id, p.amount, p.status
FROM payments p
WHERE p.order_id NOT IN (SELECT id FROM orders WHERE store_id IN (3, 5, 20));

select *, trim(txn_type) as clean_txn_type, case when is_flagged then 'Yes' else 'No' end as is_flagged_label
from transactions
where txn_time < '2024-02-16';

SELECT *, LENGTH(status) AS status_length, LOWER(account_type) AS account_type_lower
FROM accounts
WHERE status IN ('OPEN', 'FROZEN', 'CLOSED') AND status <> 'OPEN';

SELECT *
FROM employees
WHERE is_remote;

SELECT DATE_TRUNC('MONTH', launch_date) AS launch_month, MIN(launch_date) AS first_launch_date, SUM(CASE WHEN brand = 'Acme' THEN cost ELSE 0 END) AS acme_cost
FROM products
GROUP BY DATE_TRUNC('MONTH', launch_date);

SELECT DATE_TRUNC('MONTH', order_date) AS order_month, COUNT(CASE WHEN status = 'CANCELLED' THEN 1 END) AS cancelled_count, COUNT(discount) AS discount_count
FROM orders
GROUP BY 1;

SELECT YEAR(end_date) AS end_year, SUM(CASE WHEN plan = 'standard' THEN monthly_fee ELSE 0 END) AS standard_monthly_fee, COUNT(monthly_fee) AS monthly_fee_count
FROM subscriptions
GROUP BY YEAR(end_date);

SELECT DATE_FORMAT(launch_date, 'yyyy-MM') AS launch_month, SUM(CASE WHEN brand = 'Acme' THEN 1 ELSE 0 END) AS acme_count, ROUND((100 * SUM(CASE WHEN category = 'Electronics' THEN 1 ELSE 0 END)) / COUNT(*), 1) AS pct_electronics
FROM products
GROUP BY DATE_FORMAT(launch_date, 'yyyy-MM');

select *
from (
    select
        id,
        device_code,
        humidity,
        temp_c
    from device_readings
) src
unpivot include nulls (
    value for metric in (humidity, temp_c)
);

SELECT id, dept_name, LENGTH(location) AS location_length
FROM departments
WHERE NOT ((budget BETWEEN 1962000 AND 3283000 AND location NOT IN ('Berlin', 'Singapore', 'London')) OR location IN ('Tokyo', 'Singapore'));

SELECT txn_type, is_flagged, amount
FROM transactions
WHERE amount < 3400 AND (txn_time < '2023-03-01' OR is_flagged);

WITH prev_events AS (
    SELECT *, LAG(reading_ts) OVER (PARTITION BY device_code ORDER BY reading_ts ASC, id ASC) AS prev_reading_ts
    FROM device_readings
),
flagged AS (
    SELECT *, CASE WHEN prev_reading_ts IS NULL OR reading_ts > prev_reading_ts + INTERVAL '20' MINUTE THEN 1 ELSE 0 END AS session_start_flag
    FROM prev_events
)
SELECT *, SUM(session_start_flag) OVER (PARTITION BY device_code ORDER BY reading_ts ASC, id ASC ROWS BETWEEN UNBOUNDED PRECEDING AND CURRENT ROW) AS session_no
FROM flagged;

WITH with_prev AS (
    SELECT *, LAG(event_time) OVER (PARTITION BY page ORDER BY event_time, id) AS prev_event_time
    FROM web_events
),
flagged AS (
    SELECT *, CASE WHEN prev_event_time IS NULL OR event_time > prev_event_time + INTERVAL 14 DAYS THEN 1 ELSE 0 END AS is_new_burst
    FROM with_prev
)
SELECT *, SUM(is_new_burst) OVER (PARTITION BY page ORDER BY event_time, id ROWS BETWEEN UNBOUNDED PRECEDING AND CURRENT ROW) AS session_id_2
FROM flagged;

WITH with_prev AS (
    SELECT *, LAG(txn_time) OVER (PARTITION BY account_id ORDER BY txn_time, id) AS prev_txn_time
    FROM transactions
),
gaps AS (
    SELECT *, CASE WHEN prev_txn_time IS NULL OR txn_time > prev_txn_time + INTERVAL '14' DAY THEN 1 ELSE 0 END AS is_new_session
    FROM with_prev
)
SELECT *, SUM(is_new_session) OVER (PARTITION BY account_id ORDER BY txn_time, id ROWS BETWEEN UNBOUNDED PRECEDING AND CURRENT ROW) AS session_id
FROM gaps;

WITH prev_events AS (
    SELECT *, LAG(started_at) OVER (PARTITION BY device ORDER BY started_at, id) AS prev_started_at
    FROM sessions
),
with_gaps AS (
    SELECT *, CASE WHEN prev_started_at IS NULL OR started_at > prev_started_at + INTERVAL 7 DAYS THEN 1 ELSE 0 END AS session_start_flag
    FROM prev_events
)
SELECT *, SUM(session_start_flag) OVER (PARTITION BY device ORDER BY started_at, id ROWS BETWEEN UNBOUNDED PRECEDING AND CURRENT ROW) AS burst_id
FROM with_gaps;

select *
from inventory
qualify rank() over (partition by product_id order by quantity nulls first) = 1;

SELECT a.id, a.opened_date, a.status
FROM accounts a
WHERE a.status <> 'CLOSED' AND NOT EXISTS (SELECT 1 FROM transactions t WHERE t.account_id = a.id);

SELECT d.id, d.dept_name, d.budget
FROM departments d
WHERE d.budget <= 2531000 AND NOT EXISTS (SELECT 1 FROM employees e WHERE e.dept_id = d.id);

SELECT c.id, c.segment
FROM customers c
WHERE c.city <> 'Tokyo' AND NOT EXISTS (SELECT 1 FROM orders o WHERE o.customer_id = c.id AND o.customer_id IN (11, 17, 20));

select id, product_id, revenue
from (
    select *, rank() over (partition by product_id order by revenue desc) as pos
    from store_sales
    where sale_date < '2024-05-12'
) as r
where pos = 1;

SELECT store_name, opened_date, sqft
FROM stores
WHERE store_name IS NULL AND store_name LIKE '%Exp%';

SELECT AVG(quantity) AS avg_quantity, SUM(unit_price * quantity) AS revenue
FROM order_items
WHERE order_id IN (12, 19, 34);

select *
from (
    select case when budget >= 3469000 then 'high' when budget >= 1484000 then 'mid' else 'low' end as budget_bucket, sum(budget) as total_budget
    from departments
    group by case when budget >= 3469000 then 'high' when budget >= 1484000 then 'mid' else 'low' end
) as sub
where total_budget > 9749000
order by budget_bucket;

select *
from (
    select case when duration_sec >= 380 then 'high' when duration_sec >= 127 then 'mid' else 'low' end as duration_sec_bucket, avg(duration_sec) as avg_duration_sec
    from web_events
    group by case when duration_sec >= 380 then 'high' when duration_sec >= 127 then 'mid' else 'low' end
) as agg
where avg_duration_sec > 340
order by avg_duration_sec asc;

select *
from (
    select city, sum(case when city = 'Bangkok' then rating else 0 end) as bangkok_rating, sort_array(collect_set(city)) as city_list
    from suppliers
    where supplier_name like 'Tok%'
    group by city
) as agg
where bangkok_rating >= 59;
